CREATE TABLE public.departments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, description text, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT departments_name_length CHECK (char_length(btrim(name)) BETWEEN 2 AND 120));
GRANT SELECT ON public.departments TO anon, authenticated;
GRANT INSERT, UPDATE ON public.departments TO authenticated;
GRANT ALL ON public.departments TO service_role;
ALTER TABLE public.departments ENABLE ROW LEVEL SECURITY;
CREATE POLICY "active departments readable" ON public.departments FOR SELECT TO anon, authenticated USING (is_active OR public.is_staff(auth.uid()));
CREATE POLICY "staff insert departments" ON public.departments FOR INSERT TO authenticated WITH CHECK (public.is_staff(auth.uid()));
CREATE POLICY "staff update departments" ON public.departments FOR UPDATE TO authenticated USING (public.is_staff(auth.uid())) WITH CHECK (public.is_staff(auth.uid()));
ALTER TABLE public.profiles ADD COLUMN student_code text, ADD COLUMN department_id uuid REFERENCES public.departments(id) ON DELETE SET NULL;
CREATE UNIQUE INDEX profiles_student_code_unique ON public.profiles(lower(student_code)) WHERE student_code IS NOT NULL;
CREATE INDEX profiles_department_level_idx ON public.profiles(department_id,level);
CREATE POLICY "staff update profiles" ON public.profiles FOR UPDATE TO authenticated USING (public.is_staff(auth.uid())) WITH CHECK (public.is_staff(auth.uid()));
ALTER TABLE public.subjects ADD COLUMN department_id uuid REFERENCES public.departments(id) ON DELETE SET NULL;
CREATE INDEX subjects_department_level_idx ON public.subjects(department_id,level);
ALTER TABLE public.announcements ADD COLUMN target_department_ids uuid[] NOT NULL DEFAULT '{}', ADD COLUMN target_levels text[] NOT NULL DEFAULT '{}';
ALTER TABLE public.events ADD COLUMN target_department_ids uuid[] NOT NULL DEFAULT '{}', ADD COLUMN target_levels text[] NOT NULL DEFAULT '{}';
ALTER TABLE public.notifications ADD COLUMN target_department_ids uuid[] NOT NULL DEFAULT '{}', ADD COLUMN target_levels text[] NOT NULL DEFAULT '{}';
CREATE TABLE public.lecture_resources(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lecture_id uuid NOT NULL REFERENCES public.lectures(id) ON DELETE CASCADE, name text NOT NULL, description text, url text NOT NULL, resource_type text NOT NULL DEFAULT 'other' CHECK(resource_type IN ('pdf','video','external','other')), drive_file_id text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CONSTRAINT lecture_resources_name_length CHECK(char_length(btrim(name)) BETWEEN 1 AND 180), CONSTRAINT lecture_resources_url_scheme CHECK(url ~* '^https?://'));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.lecture_resources TO authenticated;
GRANT ALL ON public.lecture_resources TO service_role;
ALTER TABLE public.lecture_resources ENABLE ROW LEVEL SECURITY;
CREATE INDEX lecture_resources_lecture_idx ON public.lecture_resources(lecture_id,created_at DESC);
CREATE OR REPLACE FUNCTION public.can_access_subject(_user_id uuid,_subject_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_staff(_user_id) OR EXISTS(SELECT 1 FROM public.subjects s JOIN public.profiles p ON p.id=_user_id WHERE s.id=_subject_id AND (s.department_id IS NULL OR s.department_id=p.department_id) AND (s.level IS NULL OR s.level=p.level)) $$;
CREATE OR REPLACE FUNCTION public.matches_content_target(_user_id uuid,_department_ids uuid[],_levels text[]) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=_user_id AND (coalesce(cardinality(_department_ids),0)=0 OR p.department_id=ANY(_department_ids)) AND (coalesce(cardinality(_levels),0)=0 OR p.level=ANY(_levels))) $$;
CREATE OR REPLACE FUNCTION public.validate_content_target() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM unnest(coalesce(new.target_department_ids,'{}'::uuid[])) d(id) LEFT JOIN public.departments dep ON dep.id=d.id AND dep.is_active WHERE dep.id IS NULL) THEN RAISE EXCEPTION 'كل الأقسام المستهدفة يجب أن تكون موجودة ومفعّلة'; END IF; RETURN new; END $$;
CREATE TRIGGER trg_validate_announcement_target BEFORE INSERT OR UPDATE OF target_department_ids ON public.announcements FOR EACH ROW EXECUTE FUNCTION public.validate_content_target();
CREATE TRIGGER trg_validate_event_target BEFORE INSERT OR UPDATE OF target_department_ids ON public.events FOR EACH ROW EXECUTE FUNCTION public.validate_content_target();
CREATE TRIGGER trg_validate_notification_target BEFORE INSERT OR UPDATE OF target_department_ids ON public.notifications FOR EACH ROW EXECUTE FUNCTION public.validate_content_target();
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE _code text:=btrim(coalesce(new.raw_user_meta_data->>'student_code','')); _department uuid; BEGIN BEGIN _department:=nullif(new.raw_user_meta_data->>'department_id','')::uuid; EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'القسم الدراسي غير صالح'; END; IF char_length(_code)<2 OR char_length(_code)>40 THEN RAISE EXCEPTION 'كود الطالب مطلوب ويجب أن يتراوح بين حرفين و40 حرفًا'; END IF; IF char_length(btrim(coalesce(new.raw_user_meta_data->>'full_name','')))<5 OR coalesce(new.raw_user_meta_data->>'full_name','') !~ '[[:space:]]' OR coalesce(new.raw_user_meta_data->>'phone','') !~ '^01[0125][0-9]{8}$' THEN RAISE EXCEPTION 'بيانات الطالب أو رقم الهاتف غير صالحة'; END IF; IF NOT EXISTS(SELECT 1 FROM public.departments WHERE id=_department AND is_active) THEN RAISE EXCEPTION 'اختر قسمًا دراسيًا موجودًا ومفعّلًا'; END IF; INSERT INTO public.profiles(id,full_name,phone,student_code,department_id) VALUES(new.id,btrim(coalesce(new.raw_user_meta_data->>'full_name','')),coalesce(new.raw_user_meta_data->>'phone',''),_code,_department); PERFORM pg_advisory_xact_lock(8302028); IF NOT EXISTS(SELECT 1 FROM public.user_roles WHERE role='owner') THEN INSERT INTO public.user_roles(user_id,role) VALUES(new.id,'owner'); ELSE INSERT INTO public.user_roles(user_id,role) VALUES(new.id,'student'); END IF; INSERT INTO public.subscriptions(user_id,status) VALUES(new.id,'awaiting_payment'); RETURN new; END $$;
CREATE OR REPLACE FUNCTION public.protect_profile_phone() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NOT public.is_staff(auth.uid()) THEN new.phone:=old.phone; new.student_code:=old.student_code; new.department_id:=old.department_id; new.level:=old.level; END IF; new.updated_at:=now(); RETURN new; END $$;
ALTER POLICY "subjects read" ON public.subjects USING(public.has_access(auth.uid()) AND public.can_access_subject(auth.uid(),id));
ALTER POLICY "lectures read" ON public.lectures USING(public.has_access(auth.uid()) AND public.can_access_subject(auth.uid(),subject_id));
ALTER POLICY "ann read" ON public.announcements USING(public.is_staff(auth.uid()) OR (public.has_access(auth.uid()) AND public.matches_content_target(auth.uid(),target_department_ids,target_levels)));
ALTER POLICY "events read" ON public.events USING(public.is_staff(auth.uid()) OR (public.has_access(auth.uid()) AND public.matches_content_target(auth.uid(),target_department_ids,target_levels) AND (subject_id IS NULL OR public.can_access_subject(auth.uid(),subject_id))));
ALTER POLICY "notif read" ON public.notifications USING(user_id=auth.uid() OR (user_id IS NULL AND public.has_access(auth.uid()) AND public.matches_content_target(auth.uid(),target_department_ids,target_levels)) OR public.is_staff(auth.uid()));
CREATE POLICY "lecture resources read" ON public.lecture_resources FOR SELECT TO authenticated USING(public.has_access(auth.uid()) AND EXISTS(SELECT 1 FROM public.lectures l WHERE l.id=lecture_id AND public.can_access_subject(auth.uid(),l.subject_id)));
CREATE POLICY "lecture resources staff write" ON public.lecture_resources FOR ALL TO authenticated USING(public.is_staff(auth.uid())) WITH CHECK(public.is_staff(auth.uid()));
CREATE TABLE public.announcement_reads(user_id uuid NOT NULL DEFAULT auth.uid(), announcement_id uuid NOT NULL REFERENCES public.announcements(id) ON DELETE CASCADE, read_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,announcement_id));
GRANT SELECT,INSERT ON public.announcement_reads TO authenticated;
GRANT ALL ON public.announcement_reads TO service_role;
ALTER TABLE public.announcement_reads ENABLE ROW LEVEL SECURITY;
CREATE POLICY "announcement reads own select" ON public.announcement_reads FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY "announcement reads own insert" ON public.announcement_reads FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.announcements a WHERE a.id=announcement_id));
CREATE OR REPLACE FUNCTION public.lecture_storage_subject(_path text) RETURNS uuid LANGUAGE plpgsql IMMUTABLE SET search_path=public,storage AS $$ BEGIN RETURN (storage.foldername(_path))[1]::uuid; EXCEPTION WHEN OTHERS THEN RETURN null; END $$;
ALTER POLICY "lectures read" ON storage.objects USING(bucket_id='lectures' AND (public.is_staff(auth.uid()) OR (public.has_access(auth.uid()) AND public.can_access_subject(auth.uid(),public.lecture_storage_subject(name)))));